#import <UIKit/UIKit.h>
#import "ResearchUI.h"
#import <objc/runtime.h>
#import "AlwaysOnAudio.h"
@interface TIOAlwaysOnAudioPanel:UITableViewController
@property(nonatomic) NSDictionary *nativeStatus;
@property(nonatomic) NSArray *files;
@property(nonatomic) BOOL busy;
@end
@implementation TIOAlwaysOnAudioPanel
- (void)viewDidLoad{[super viewDidLoad];self.title=@"AI Notes Audio";self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemRefresh target:self action:@selector(refresh)];[self refresh];}
- (void)refresh{if(self.busy)return;self.nativeStatus=TIOAOStatus();self.busy=YES;dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSArray *files=TIOAOAudioFiles([NSURL fileURLWithPath:NSHomeDirectory()]);dispatch_async(dispatch_get_main_queue(),^{self.files=files;self.busy=NO;[self.tableView reloadData];});});}
- (void)message:(NSString *)text{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"AI Notes Audio" message:text preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"OK" style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:a animated:YES completion:nil];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 2;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==0?2:MAX(1,(NSInteger)self.files.count);}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return s==0?@"Local Audio Recording":@"Saved Audio Copies";}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return s==0?@"Only saves conversation audio received after enabling. Does not trigger microphone or AI notes independently. Stored locally only; files are not auto-deleted. Verify switch after app restart.":@"Stop current AI notes in the official app first, then refresh and select a file to share. Lists official debug session recordings.";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)ip{UITableViewCell *c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];TIOStyleResearchCell(c);c.detailTextLabel.numberOfLines=0;
    if(ip.section==0&&ip.row==0){c.textLabel.text=@"Save Subsequent AI Notes Audio";c.detailTextLabel.text=self.nativeStatus?@"Does not alter official ASR; no auto-upload":@"Official version or audio interface not ready";UISwitch *s=[UISwitch new];s.on=[self.nativeStatus[@"dumpEnabled"] boolValue];s.enabled=self.nativeStatus!=nil&&!self.busy;[s addTarget:self action:@selector(toggle:) forControlEvents:UIControlEventValueChanged];c.accessoryView=s;}
    else if(ip.section==0){c.textLabel.text=[self.nativeStatus[@"alwaysOnRunning"] boolValue]?@"AI Notes running; please stop before sharing":@"AI Notes not currently running";c.detailTextLabel.text=[NSString stringWithFormat:@"Live packets: %@ / Cached packets: %@; %@",self.nativeStatus[@"realtimePackets"]?:@0,self.nativeStatus[@"cachedPackets"]?:@0,self.nativeStatus?@"Official status read":@"Interface unavailable"] ;}
    else if(!self.files.count){c.textLabel.text=self.busy?@"Reading…":@"No saved audio found";c.detailTextLabel.text=@"Run official AI Notes once after enabling saving, then stop and refresh.";c.selectionStyle=UITableViewCellSelectionStyleNone;}
    else{NSDictionary *r=self.files[ip.row];NSDateFormatter *f=[NSDateFormatter new];f.dateFormat=@"MM-dd HH:mm:ss";c.textLabel.text=[NSString stringWithFormat:@"%@ · %@",r[@"kind"],[f stringFromDate:r[@"date"]]];c.detailTextLabel.text=[NSString stringWithFormat:@"%@ · %@",[(NSURL *)r[@"url"] pathExtension],[NSByteCountFormatter stringFromByteCount:[r[@"bytes"] longLongValue] countStyle:NSByteCountFormatterCountStyleFile]];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;}return c;
}
- (void)toggle:(UISwitch *)sender{BOOL requested=sender.on;sender.on=[self.nativeStatus[@"dumpEnabled"] boolValue];if(!requested){BOOL ok=TIOAOSetAudioSaving(NO);[self refresh];if(!ok)[self message:@"Failed to verify toggle state. Stopping official AI Notes halts new audio input."];return;}
    UIAlertController *a=[UIAlertController alertControllerWithTitle:@"Save Subsequent AI Notes Audio?" message:@"Saves raw conversation audio locally on your device for future AI Notes sessions. Ensure consent. Stored locally only; no upload, no auto-deletion." preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"Enable Local Audio Saving" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){BOOL ok=TIOAOSetAudioSaving(YES);[self refresh];if(!ok)[self message:@"Setting verification failed. Check actual switch state."];else [self message:@"Audio saving enabled. Start a short AI Notes session in official app, stop it, then refresh here."];}]];[self presentViewController:a animated:YES completion:nil];
}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)ip{[t deselectRowAtIndexPath:ip animated:YES];if(ip.section!=1||self.busy||ip.row>=((NSInteger)self.files.count))return;NSDictionary *s=TIOAOStatus();if(!s||[s[@"alwaysOnRunning"] boolValue]){[self message:@"Please stop official AI Notes first, wait for file flush, then refresh to share."];return;}
    if([s[@"dumpEnabled"] boolValue]){[self message:@"Please turn off audio saving above so the app finishes writing the file, then refresh."];return;}
    NSURL *source=self.files[ip.row][@"url"];self.busy=YES;dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSError *error=nil;NSURL *copy=TIOAOAudioCopy([NSURL fileURLWithPath:NSHomeDirectory()],source,&error);dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;if(!copy){[self message:error.localizedDescription];return;}UIActivityViewController *share=[[UIActivityViewController alloc]initWithActivityItems:@[copy] applicationActivities:nil];share.popoverPresentationController.sourceView=self.view;share.popoverPresentationController.sourceRect=CGRectMake(self.view.bounds.size.width/2,100,1,1);[self presentViewController:share animated:YES completion:nil];});});
}
@end
static id (*AudioPriorCell)(id,SEL,id,id);
static id (*AudioPriorFooter)(id,SEL,id,NSInteger);
static void (*AudioPriorSelect)(id,SEL,id,id);
static id AudioCell(id self,SEL cmd,id table,NSIndexPath *ip){if(ip.section!=0||ip.row!=2)return AudioPriorCell(self,cmd,table,ip);UITableViewCell *c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];TIOStyleResearchCell(c);c.textLabel.text=@"Audio Saving & Sharing";c.detailTextLabel.text=@"Local saving toggle · Saved audio · AirDrop";c.detailTextLabel.numberOfLines=0;c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
static id AudioFooter(id self,SEL cmd,id table,NSInteger s){if(s==0)return @"Text only contains transcripts captured after enabling. Audio uses official local saving interface and only captures subsequent sessions.";return AudioPriorFooter(self,cmd,table,s);}
static void AudioSelect(id self,SEL cmd,UITableView *t,NSIndexPath *ip){if(ip.section!=0||ip.row!=2){AudioPriorSelect(self,cmd,t,ip);return;}[t deselectRowAtIndexPath:ip animated:YES];[[(UIViewController *)self navigationController] pushViewController:[[TIOAlwaysOnAudioPanel alloc]initWithStyle:UITableViewStyleInsetGrouped] animated:YES];}
static void AudioMarker(id self,SEL cmd){}
void TIOInstallAlwaysOnAudioMenu(void){Class cls=NSClassFromString(@"TIOLifelogExportsPanel");SEL marker=NSSelectorFromString(@"tio_alwaysOnAudioMenuV1");if(!cls||class_getInstanceMethod(cls,marker))return;Method cell=class_getInstanceMethod(cls,@selector(tableView:cellForRowAtIndexPath:)),footer=class_getInstanceMethod(cls,@selector(tableView:titleForFooterInSection:)),select=class_getInstanceMethod(cls,@selector(tableView:didSelectRowAtIndexPath:));if(!cell||!footer||!select)return;if(!class_addMethod(cls,marker,(IMP)AudioMarker,"v@:"))return;AudioPriorCell=(void *)method_setImplementation(cell,(IMP)AudioCell);AudioPriorFooter=(void *)method_setImplementation(footer,(IMP)AudioFooter);AudioPriorSelect=(void *)method_setImplementation(select,(IMP)AudioSelect);}
#ifdef TIO_AO_AUDIO_HOTLOAD
__attribute__((constructor))static void AudioInstall(void){dispatch_async(dispatch_get_main_queue(),^{if([NSBundle.mainBundle.bundleIdentifier isEqual:@"com.rayneo.venus.pub"]&&[[NSBundle.mainBundle objectForInfoDictionaryKey:@"CFBundleVersion"] isEqual:@"67"])TIOInstallAlwaysOnAudioMenu();});}
#endif
